    continue;
  }
  const expected = m[1];
  let got;
  try {
    got = punycodeEncode(label);
  } catch (e) {
    check(`exe encode ${JSON.stringify(label)}`, false, `threw ${e.message}`);
    continue;
  }
  check(`exe encode ${JSON.stringify(label)}`, got === expected, `got ${JSON.stringify(got)}, want ${JSON.stringify(expected)}`);
  exeChecked++;
}
console.log(`executable cross-checks: ${exeChecked} labels checked, ${exeSkipped} skipped (not valid IDNA)`);
check('at least 20 executable labels checked', exeChecked >= 20, `only ${exeChecked}`);

// --- 3. Cross-check decode against reference executable ---
const alabels = ['xn--fsq', 'xn--bcher-kva', 'xn--80adxhks', 'xn--strae-oqa', 'xn--n3h', 'xn--maana-pta'];
for (const alabel of alabels) {
  let out;
  try {
    out = execFileSync(EXE, ['--domain', `${alabel}.cn`, '--strict', 'True'], { encoding: 'utf8' });
  } catch (e) {
    check(`exe decode ${alabel}`, false, `executable failed: ${e.message.split('\n')[0]}`);
    continue;
  }
  // The ulabel line: find a bare non-ascii line in the output.
  const lines = out.split('\n').map((l) => l.trim()).filter(Boolean);
  const uline = lines.find((l) => /[^\x00-\x7f]/.test(l) && !l.startsWith("b'"));
  if (!uline) {
    check(`exe decode ${alabel}`, false, `no ulabel in output: ${out.trim()}`);
    continue;
  }
  const ascii = alabel.slice(4);
  let got;
  try {
    got = punycodeDecode(ascii);
  } catch (e) {
    check(`exe decode ${alabel}`, false, `threw ${e.message}`);
    continue;
  }
  check(`exe decode ${alabel}`, got === uline, `got ${JSON.stringify(got)}, want ${JSON.stringify(uline)}`);
}

console.log(`\n${passed} passed, ${failed} failed`);
if (failed > 0) {
  console.error('Failures:\n' + failures.join('\n'));
  process.exit(1);
}

