// Python repr() emulation helpers.

// Non-printable per Python str.isprintable(): general categories C* (Cc, Cf,
// Cs, Co, Cn-unassigned) and separators Zl/Zp/Zs, with U+0020 SPACE excepted.
const NON_PRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function hexEscape(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Python repr() of a str.
export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (isPrintable(ch)) out += ch;
    else out += hexEscape(cp);
  }
  return out + quote;
}

// Python repr() of a bytes object. `s` is a JS string whose char codes are
// treated as byte values (our content is ASCII).
export function pyBytesRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = 'b' + quote;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const b = s.charCodeAt(i) & 0xff;
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (b >= 0x20 && b <= 0x7e) out += ch;
    else out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + quote;
}

// Python str() of a bool.
export function pyBool(b) {
  return b ? 'True' : 'False';
}

