// Verification for /output/lib/pyrepr.mjs and /output/lib/argparse.mjs.
// (a) Unit-tests pyrepr against hand-computed Python repr() expectations.
// (b) Runs a matrix of argv vectors through both the reference executable and
//     the node harness (tools/argparse-harness.mjs), comparing stderr and exit
//     code byte-for-byte, plus stdout for help/error cases; for successful
//     parses the harness stdout is checked against the expected JSON.
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { pyStrRepr, pyBytesRepr, pyBool } from '../lib/pyrepr.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const EXE = '/workspace/dataset/test3_executable';
const HARNESS = path.join(HERE, 'argparse-harness.mjs');

let failures = 0;
function check(label, actual, expected) {
  if (actual === expected) {
    console.log(`ok   ${label}`);
  } else {
    failures++;
    console.log(`FAIL ${label}`);
    console.log(`  expected: ${JSON.stringify(expected)}`);
    console.log(`  actual:   ${JSON.stringify(actual)}`);
  }
}

// ---------- (a) pyrepr unit tests ----------
console.log('--- pyrepr ---');
check('pyStrRepr plain ascii', pyStrRepr('abc'), "'abc'");
check('pyStrRepr empty', pyStrRepr(''), "''");
check('pyStrRepr apostrophe', pyStrRepr("it's"), '"it\'s"');
check('pyStrRepr double quote', pyStrRepr('say "hi"'), `'say "hi"'`);
check('pyStrRepr both quotes', pyStrRepr(`a'b"c`), `'a\\'b"c'`);
check('pyStrRepr backslash', pyStrRepr('a\\b'), `'a\\\\b'`);
check('pyStrRepr control chars', pyStrRepr('a\nb\tc\rd'), `'a\\nb\\tc\\rd'`);
check('pyStrRepr NUL', pyStrRepr('\x00'), `'\\x00'`);
check('pyStrRepr VT', pyStrRepr('\x0b'), `'\\x0b'`);
check('pyStrRepr soft hyphen', pyStrRepr('exa­mple'), `'exa\\xadmple'`);
check('pyStrRepr emoji astral', pyStrRepr('\u{1f600}'), `'\u{1f600}'`);
check('pyStrRepr space', pyStrRepr('a b'), `'a b'`);
check('pyStrRepr DEL 0x7F', pyStrRepr('\x7f'), `'\\x7f'`);
check('pyStrRepr U+0080', pyStrRepr(''), `'\\x80'`);
check('pyStrRepr U+2028', pyStrRepr(' '), `'\\u2028'`);
check('pyStrRepr U+2029', pyStrRepr(' '), `'\\u2029'`);
check('pyStrRepr U+0378 unassigned', pyStrRepr('͸'), `'\\u0378'`);
check('pyStrRepr U+00A0 nbsp', pyStrRepr(' '), `'\\xa0'`);
check('pyStrRepr U+200B zwsp', pyStrRepr('​'), `'\\u200b'`);
check('pyStrRepr U+E0001 tag', pyStrRepr('\u{e0001}'), `'\\U000e0001'`);
check('pyStrRepr e-acute printable', pyStrRepr('é'), `'é'`);
check('pyStrRepr CJK printable', pyStrRepr('例.cn'), `'例.cn'`);

check('pyBytesRepr punycode', pyBytesRepr('xn--fsq.cn'), `b'xn--fsq.cn'`);
check('pyBytesRepr apostrophe', pyBytesRepr("ab'cd"), `b"ab'cd"`);
check('pyBytesRepr double quote', pyBytesRepr('ab"cd'), `b'ab"cd'`);
check('pyBytesRepr both quotes', pyBytesRepr(`a'b"c`), `b'a\\'b"c'`);
check('pyBytesRepr backslash', pyBytesRepr('a\\b'), `b'a\\\\b'`);
check('pyBytesRepr DEL', pyBytesRepr('\x7f'), `b'\\x7f'`);
check('pyBytesRepr newline', pyBytesRepr('a\nb'), `b'a\\nb'`);

check('pyBool true', pyBool(true), 'True');
check('pyBool false', pyBool(false), 'False');

// ---------- (b) argparse matrix vs reference executable ----------
console.log('--- argparse matrix ---');
// expected: for successful parses, the JSON the harness must print.
const cases = [
  { argv: [] },
  { argv: ['--domain', 'x'] },
  { argv: ['--strict', 'True'] },
  { argv: ['--foo', 'bar'] },
  { argv: ['--domain'] },
  { argv: ['--domain', 'x', '--strict'] },
  { argv: ['--dom', 'x', '--s', 'True'], expected: { domain: 'x', strict: true } },
  { argv: ['--domain=x', '--strict=False'], expected: { domain: 'x', strict: true } },
  { argv: ['--do=a', '--st=b'], expected: { domain: 'a', strict: true } },
  { argv: ['--d=x', '--s', ''], expected: { domain: 'x', strict: false } },
  { argv: ['--domain', 'x', 'extra'] },
  { argv: ['-h'] },
  { argv: ['--h'] },
  { argv: ['--help'] },
  { argv: ['--foo', '-h'] },
  { argv: ['--domain', 'x', '--strict', '1', '-h'] },
  { argv: ['--domain', 'x', '--strict', '1', '--foo', 'bar'] },
  { argv: ['--domain', 'x', '--strict', '1', 'extra1', 'extra2'] },
  { argv: ['--domain', '-1', '--strict', '0'], expected: { domain: '-1', strict: true } },
  { argv: ['--domain', '-1.5', '--strict', '1'], expected: { domain: '-1.5', strict: true } },
  { argv: ['--domain', '-', '--strict', '1'], expected: { domain: '-', strict: true } },
  { argv: ['--domain', '-1a', '--strict', '1'] },
  { argv: ['--domain', '-strict'] },
  { argv: ['--domain', '--strict', '1'] },
  { argv: ['--foo', '--domain'] },
  { argv: ['--domain', 'x', '--domain', 'y', '--strict', '1'], expected: { domain: 'y', strict: true } },
  { argv: ['--domainx', 'y'] },
  { argv: ['-x'] },
  { argv: ['--strict', '', '--domain', 'x'], expected: { domain: 'x', strict: false } },
  { argv: ['--domain', 'x', '--strict', '1', '--'] },
  { argv: ['--domain', 'x', '--strict', '1', '--', '--foo'] },
  { argv: ['--domain', 'x', '--strict', '1', '--', '--domain', 'y'] },
];

for (const c of cases) {
  const label = `argv=${JSON.stringify(c.argv)}`;
  const ref = spawnSync(EXE, c.argv, { encoding: 'buffer' });
  const got = spawnSync('node', [HARNESS, ...c.argv], { encoding: 'buffer' });
  const refCode = ref.status;
  const gotCode = got.status;

  let caseFail = false;
  const bad = (what, exp, act) => {
    caseFail = true;
    console.log(`  MISMATCH ${what}:\n    ref:  ${JSON.stringify(exp)}\n    got:  ${JSON.stringify(act)}`);
  };

  if (c.expected) {
    // Successful parse: executable runs the IDNA script (stdout differs by
    // design), so compare exit code + stderr, and check harness JSON.
    if (refCode !== 0 || gotCode !== 0) bad('exit code', refCode, gotCode);
    if (!got.stderr.equals(ref.stderr)) bad('stderr', ref.stderr.toString(), got.stderr.toString());
    const gotJson = got.stdout.toString();
    const wantJson = JSON.stringify(c.expected) + '\n';
    if (gotJson !== wantJson) bad('harness stdout', wantJson, gotJson);
  } else {
    // Help/error case: compare exit code, stdout, stderr byte-for-byte.
    if (refCode !== gotCode) bad('exit code', refCode, gotCode);
    if (!got.stdout.equals(ref.stdout)) bad('stdout', ref.stdout.toString(), got.stdout.toString());
    if (!got.stderr.equals(ref.stderr)) bad('stderr', ref.stderr.toString(), got.stderr.toString());
  }

  if (caseFail) failures++;
  console.log(`${caseFail ? 'FAIL' : 'ok  '} ${label}`);
}

console.log(`\n${failures === 0 ? 'ALL PASS' : failures + ' FAILURE(S)'}`);
process.exit(failures === 0 ? 0 : 1);

