check('pyBytesRepr both quotes', pyBytesRepr(`a'b"c`), `b'a\\'b"c'`);
check('pyBytesRepr backslash', pyBytesRepr('a\\b'), `b'a\\\\b'`);
check('pyBytesRepr DEL', pyBytesRepr('\x7f'), `b'\\x7f'`);
check('pyBytesRepr newline', pyBytesRepr('a\nb'), `b'a\\nb'`);

check('pyBool true', pyBool(true), 'True');
check('pyBool false', pyBool(false), 'False');

// ---------- (b) argparse matrix vs reference executable ----------
console.log('--- argparse matrix ---');
// expected: for successful parses, the JSON the harness must print.
const cases = [
  { argv: [] },
  { argv: ['--domain', 'x'] },
  { argv: ['--strict', 'True'] },
  { argv: ['--foo', 'bar'] },
  { argv: ['--domain'] },
  { argv: ['--domain', 'x', '--strict'] },
  { argv: ['--dom', 'x', '--s', 'True'], expected: { domain: 'x', strict: true } },
  { argv: ['--domain=x', '--strict=False'], expected: { domain: 'x', strict: true } },
  { argv: ['--do=a', '--st=b'], expected: { domain: 'a', strict: true } },
  { argv: ['--d=x', '--s', ''], expected: { domain: 'x', strict: false } },
  { argv: ['--domain', 'x', 'extra'] },
  { argv: ['-h'] },
  { argv: ['--h'] },
  { argv: ['--help'] },
  { argv: ['--foo', '-h'] },
  { argv: ['--domain', 'x', '--strict', '1', '-h'] },
  { argv: ['--domain', 'x', '--strict', '1', '--foo', 'bar'] },
  { argv: ['--domain', 'x', '--strict', '1', 'extra1', 'extra2'] },
  { argv: ['--domain', '-1', '--strict', '0'], expected: { domain: '-1', strict: true } },
  { argv: ['--domain', '-1.5', '--strict', '1'], expected: { domain: '-1.5', strict: true } },
  { argv: ['--domain', '-', '--strict', '1'], expected: { domain: '-', strict: true } },
  { argv: ['--domain', '-1a', '--strict', '1'] },
  { argv: ['--domain', '-strict'] },
  { argv: ['--domain', '--strict', '1'] },
  { argv: ['--foo', '--domain'] },
  { argv: ['--domain', 'x', '--domain', 'y', '--strict', '1'], expected: { domain: 'y', strict: true } },
  { argv: ['--domainx', 'y'] },
  { argv: ['-x'] },
  { argv: ['--strict', '', '--domain', 'x'], expected: { domain: 'x', strict: false } },
  { argv: ['--domain', 'x', '--strict', '1', '--'] },
  { argv: ['--domain', 'x', '--strict', '1', '--', '--foo'] },
  { argv: ['--domain', 'x', '--strict', '1', '--', '--domain', 'y'] },
];

for (const c of cases) {
  const label = `argv=${JSON.stringify(c.argv)}`;
  const ref = spawnSync(EXE, c.argv, { encoding: 'buffer' });
  const got = spawnSync('node', [HARNESS, ...c.argv], { encoding: 'buffer' });
  const refCode = ref.status;
  const gotCode = got.status;

  let caseFail = false;
  const bad = (what, exp, act) => {
    caseFail = true;
    console.log(`  MISMATCH ${what}:\n    ref:  ${JSON.stringify(exp)}\n    got:  ${JSON.stringify(act)}`);
  };

  if (c.expected) {
    // Successful parse: executable runs the IDNA script (stdout differs by
    // design), so compare exit code + stderr, and check harness JSON.
    if (refCode !== 0 || gotCode !== 0) bad('exit code', refCode, gotCode);
    if (!got.stderr.equals(ref.stderr)) bad('stderr', ref.stderr.toString(), got.stderr.toString());
    const gotJson = got.stdout.toString();
    const wantJson = JSON.stringify(c.expected) + '\n';
    if (gotJson !== wantJson) bad('harness stdout', wantJson, gotJson);
  } else {
    // Help/error case: compare exit code, stdout, stderr byte-for-byte.
    if (refCode !== gotCode) bad('exit code', refCode, gotCode);
    if (!got.stdout.equals(ref.stdout)) bad('stdout', ref.stdout.toString(), got.stdout.toString());
    if (!got.stderr.equals(ref.stderr)) bad('stderr', ref.stderr.toString(), got.stderr.toString());
  }

  if (caseFail) failures++;
  console.log(`${caseFail ? 'FAIL' : 'ok  '} ${label}`);
}

console.log(`\n${failures === 0 ? 'ALL PASS' : failures + ' FAILURE(S)'}`);
process.exit(failures === 0 ? 0 : 1);

