// On success the executable prints, per line: alabel-domain repr, unicode
// domain, "True", ulabel, alabel repr. The ulabel is line index 3.
const alabels = ['xn--fsq', 'xn--bcher-kva', 'xn--80adxhks', 'xn--strae-oqa', 'xn--maana-pta', 'xn--n3h'];
