  } catch (e) {
    check(`exe decode ${alabel}`, false, `executable failed: ${e.message.split('\n')[0]}`);
    continue;
  }
  const lines = out.split('\n');
  const uline = lines[3] && lines[3].trim();
  if (!uline || lines[0].startsWith('strict') || !/[^\x00-\x7f]/.test(uline)) {
