  const valid = [];
  const tasks = [];
  let doneChunks = 0;
  const totalChunks = Math.ceil(cps.length / CHUNK);
  for (let i = 0; i < cps.length; i += CHUNK) {
    const chunk = cps.slice(i, i + CHUNK);
    tasks.push(async () => {
      const v = await groupTest(chunk, (cs) => cs.map((c) => String.fromCodePoint(c)).join('.'));
      for (const c of v) valid.push(c);
      doneChunks++;
      if (doneChunks % 5000 === 0) console.log(`Sweep B: ${doneChunks}/${totalChunks} chunks`);
    });
  }
  await Promise.all(tasks.map((t) => t()));
  valid.sort((a, b) => a - b);
  fs.writeFileSync(CACHE_VALID, JSON.stringify(valid));
  console.log(`Sweep B done: ${valid.length} valid-alone code points`);
  return valid;
}

async function sweepC(validAlone) {
  let virama, zwjok;
  if (fs.existsSync(CACHE_VIRAMA)) {
    virama = JSON.parse(fs.readFileSync(CACHE_VIRAMA, 'utf8'));
    console.log(`Sweep C: loaded virama cache (${virama.length})`);
  }
  if (fs.existsSync(CACHE_ZWJOK)) {
    zwjok = JSON.parse(fs.readFileSync(CACHE_ZWJOK, 'utf8'));
    console.log(`Sweep C: loaded zwjok cache (${zwjok.length})`);
  }
  if (virama && zwjok) return { virama, zwjok };

  const CHUNK = 16; // 2-char labels, worst-case ~13B each; 16*14=224 < 253
  async function runSet(joiner) {
    const out = [];
    const tasks = [];
    let doneChunks = 0;
    const totalChunks = Math.ceil(validAlone.length / CHUNK);
    for (let i = 0; i < validAlone.length; i += CHUNK) {
      const chunk = validAlone.slice(i, i + CHUNK);
      tasks.push(async () => {
        const v = await groupTest(chunk,
          (cs) => cs.map((c) => String.fromCodePoint(c) + joiner).join('.'));
        for (const c of v) out.push(c);
        doneChunks++;
        if (doneChunks % 2000 === 0) console.log(`Sweep C: ${doneChunks}/${totalChunks} chunks`);
      });
    }
    await Promise.all(tasks.map((t) => t()));
    out.sort((a, b) => a - b);
    return out;
  }
  if (!virama) {
    virama = await runSet('‌'); // X + ZWNJ encodes strictly
    fs.writeFileSync(CACHE_VIRAMA, JSON.stringify(virama));
    console.log(`Sweep C virama (X+ZWNJ ok) done: ${virama.length}`);
  }
  if (!zwjok) {
    zwjok = await runSet('‍'); // X + ZWJ encodes strictly
    fs.writeFileSync(CACHE_ZWJOK, JSON.stringify(zwjok));
    console.log(`Sweep C zwjok (X+ZWJ ok) done: ${zwjok.length}`);
  }
  return { virama, zwjok };
}

// ----------------------------------------------------------- emit tables ----
function emitTables({ drops, maps }, valid, virama, zwjok) {
  const validRanges = toRanges(valid);
  const viramaRanges = toRanges(virama);
  const zwjokRanges = toRanges(zwjok);
  const dropRanges = toRanges(drops);

  const src = `// GENERATED FILE — do not edit by hand.
// Black-box reconstruction of the Python \`idna\` package's data tables
// (IDNA2008 validity + UTS46 remap, non-transitional) by probing a reference
// executable. Regenerate with: node /output/tools/extract-tables.mjs
//
// Conventions:
//  - Ranges are sorted, inclusive [lo, hi] pairs.
//  - REMAP_MAP entries are [cp, replacement] sorted by cp.
//  - Code points not in any map/drop structure remap as 'pass'.
//    (cp 0x00, surrogates 0xD800..0xDFFF and 0x2E '.' are all 'pass';
//     0x00 and surrogates are never valid alone; validity of 0x2E is
//     irrelevant since it is a label separator.)
//  - Code points that crash the reference executable's uts46_remap
//    (unassigned in its Unicode data) are listed in
//    /output/tools/cache-anomalies.json; they are 'pass' here.

const VALID_RANGES = ${JSON.stringify(validRanges)};
const VIRAMA_RANGES = ${JSON.stringify(viramaRanges)};
const ZWJOK_RANGES = ${JSON.stringify(zwjokRanges)};
const REMAP_DROP_RANGES = ${JSON.stringify(dropRanges)};
const REMAP_MAP = ${JSON.stringify(maps)};

function inRanges(ranges, cp) {
  let lo = 0, hi = ranges.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const r = ranges[mid];
    if (cp < r[0]) hi = mid - 1;
    else if (cp > r[1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/** true iff the code point is valid as a one-character label under strict IDNA2008. */
export function isValidAlone(cp) {
  if (cp < 1 || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) return false;
  return inRanges(VALID_RANGES, cp);
}

/** true iff the label X + U+200C (ZWNJ) encodes under strict IDNA2008 (X is virama-like). */
export function isVirama(cp) {
  return inRanges(VIRAMA_RANGES, cp);
}

/** true iff X + U+200D (ZWJ) encodes strictly (joiner context allows following ZWJ). */
export function isZwjOk(cp) {
  return inRanges(ZWJOK_RANGES, cp);
}

/** UTS46 remap of a single code point: {type:'pass'} | {type:'drop'} | {type:'map', to}. */
export function remapCodepoint(cp) {
  let lo = 0, hi = REMAP_MAP.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const e = REMAP_MAP[mid];
    if (cp < e[0]) hi = mid - 1;
    else if (cp > e[0]) lo = mid + 1;
    else return { type: 'map', to: e[1] };
  }
  if (inRanges(REMAP_DROP_RANGES, cp)) return { type: 'drop' };
  return { type: 'pass' };
}
`;
  fs.mkdirSync(LIB, { recursive: true });
  fs.writeFileSync(`${LIB}/idnaTables.mjs`, src);
  console.log(`Wrote ${LIB}/idnaTables.mjs (${(src.length / 1024).toFixed(0)} KiB)`);
  return { validRanges, viramaRanges, zwjokRanges, dropRanges, mapCount: maps.length };
}

// ----------------------------------------------------------------- main ----
const t0 = Date.now();
const remap = await sweepA();
const valid = await sweepB();
const { virama, zwjok } = await sweepC(valid);
const stats = emitTables(remap, valid, virama, zwjok);

const crashList = [...crashers].sort((a, b) => a - b);
fs.writeFileSync(CACHE_ANOM, JSON.stringify(crashList));
console.log(`Crashers (exit!=0 code points): ${crashList.length} -> ${CACHE_ANOM}`);
console.log(`Counts: validAlone=${valid.length} validRanges=${stats.validRanges.length} ` +
  `drops=${remap.drops.length} dropRanges=${stats.dropRanges.length} maps=${remap.maps.length} ` +
  `virama=${virama.length} viramaRanges=${stats.viramaRanges.length} ` +
  `zwjok=${zwjok.length} zwjokRanges=${stats.zwjokRanges.length}`);
console.log(`Elapsed: ${((Date.now() - t0) / 1000).toFixed(1)}s`);
